def letterbox_geometry(width, height, output_hw):
    oh, ow = map(int, output_hw)
    scale = min(ow / width, oh / height)
    nw, nh = (max(1, min(ow, round(width * scale))), max(1, min(oh, round(height * scale))))
    left, top = ((ow - nw) // 2, (oh - nh) // 2)
    sx, sy = (nw / width, nh / height)
    matrix = np.array([[sx, 0, left + 0.5 * sx - 0.5], [0, sy, top + 0.5 * sy - 0.5], [0, 0, 1]], dtype=np.float64)
    return (matrix, dict(new_hw=(nh, nw), pad_xy=(left, top)))

def make_letterbox(image, output_hw):
    matrix, info = letterbox_geometry(image.shape[1], image.shape[0], output_hw)
    oh, ow = output_hw
    nh, nw = info['new_hw']
    left, top = info['pad_xy']
    output = np.zeros((oh, ow), dtype=np.float32)
    output[top:top + nh, left:left + nw] = cv2.resize(image, (nw, nh), interpolation=cv2.INTER_LINEAR)
    return (output, matrix)

def xy(p, m):
    p = np.asarray(p, float).reshape(-1, 2)
    return np.c_[p, np.ones(len(p))].dot(m.T)[:, :2]

def geom(p):
    lo, hi = (p.min(0), p.max(0))
    size = hi - lo
    center = (lo + hi) / 2 + [0, LC['down_factor'] * size[1]]
    side = LC['side_factor'] * max(size)
    assert side > 1
    left, top = center - side / 2
    sx, sy = (W / side, H / side)
    return np.array([[sx, 0, sx * (0.5 - left) - 0.5], [0, sy, sy * (0.5 - top) - 0.5], [0, 0, 1.0]])

def canonical_pair(points):
    p = np.asarray(points, float).reshape(2, 2)
    if not np.isfinite(p).all():
        raise ValueError('끝점 NaN/inf')
    return p[np.lexsort((p[:, 1], p[:, 0]))]

def l5_coordinates(points, polygon):
    p = np.asarray(polygon, float).reshape(-1, 2)
    lo, hi = (p.min(0), p.max(0))
    size = hi - lo
    if not np.isfinite(p).all() or np.any(size < 1):
        raise ValueError('L5 polygon 크기 오류')
    anchor = np.array([(lo[0] + hi[0]) / 2, hi[1]])
    return ((canonical_pair(points) - anchor) / size).reshape(4)

def prior_log_score(features, prior):
    query = np.asarray(features, float).reshape(-1, 4)
    refs = np.asarray(prior['features'])
    scale = np.asarray(prior['scale']) * prior['bandwidth']
    distance = (((query[:, None] - refs[None]) / scale) ** 2).sum(2)
    log_kernel = -(prior['df'] + 4) / 2 * np.log1p(distance / prior['df'])
    terms = log_kernel + np.log(np.maximum(prior['weights'], 1e-300))[None]
    mx = terms.max(1)
    log_density = mx + np.log(np.exp(terms - mx[:, None]).sum(1))
    return np.maximum(log_density, -prior['penalty_cap'])

def heatmap_geometry(c, mat, shape):
    mapping = np.array([[1 / stride, 0, 0.5 / stride - 0.5], [0, 1 / stride, 0.5 / stride - 0.5], [0, 0, 1.0]]) @ mat
    yy, xx = np.mgrid[:shape[0], :shape[1]]
    original = xy(np.c_[xx.ravel(), yy.ravel()], np.linalg.inv(mapping))
    valid = ((original >= -0.5) & (original <= [c['width'] - 0.5, c['height'] - 0.5])).all(1).reshape(shape)
    if not valid.any():
        raise ValueError('ROI가 원본 영상과 겹치지 않습니다.')
    return (mapping, valid)

def spaced_candidates(heat, valid, mapping, polygon, settings):
    scale = np.sqrt(abs(np.linalg.det(mapping[:2, :2])))
    l5_size = float(np.ptp(np.asarray(polygon, float), axis=0).max())
    radius = max(3, int(round(settings['nms_l5_fraction'] * l5_size * scale)))
    yy, xx = np.mgrid[:heat.shape[0], :heat.shape[1]]
    scores = np.where(valid, heat, -np.inf).copy()
    points = []
    values = []
    for _ in range(settings['candidates_per_endpoint']):
        y, x = np.unravel_index(scores.argmax(), scores.shape)
        if not np.isfinite(scores[y, x]):
            break
        p = [float(x), float(y)]
        for axis, (dx, dy) in enumerate(((1, 0), (0, 1))):
            if not (0 <= x - dx and x + dx < heat.shape[1] and (0 <= y - dy) and (y + dy < heat.shape[0])):
                continue
            if not (valid[y - dy, x - dx] and valid[y + dy, x + dx]):
                continue
            a, b, d = np.log(np.maximum([heat[y - dy, x - dx], heat[y, x], heat[y + dy, x + dx]], 1e-08))
            curvature = a - 2 * b + d
            if curvature < -1e-08:
                p[axis] += float(np.clip(0.5 * (a - d) / curvature, -0.5, 0.5))
        points.append(p)
        values.append(float(heat[y, x]))
        scores[(xx - x) ** 2 + (yy - y) ** 2 <= radius ** 2] = -np.inf
    return (xy(points, np.linalg.inv(mapping)), np.asarray(values), radius)

def build_pair_bank(probabilities, baseline, c, mat, prior, settings):
    mapping, valid = heatmap_geometry(c, mat, probabilities.shape[-2:])
    a, sa, ra = spaced_candidates(probabilities[0], valid, mapping, c['l5'], settings)
    b, sb, rb = spaced_candidates(probabilities[1], valid, mapping, c['l5'], settings)
    pairs = [np.asarray(baseline, float)]
    heat_scores = [0.5 * (np.log(max(probabilities[0][valid].max(), 1e-08)) + np.log(max(probabilities[1][valid].max(), 1e-08)))]
    for i, pa in enumerate(a):
        for j, pb in enumerate(b):
            if pb[0] < pa[0] or np.linalg.norm(pb - pa) < 1:
                continue
            pair = np.stack([pa, pb])
            if np.max(abs(pair - baseline)) < 1e-06:
                continue
            pairs.append(pair)
            heat_scores.append(0.5 * (np.log(max(sa[i], 1e-08)) + np.log(max(sb[j], 1e-08))))
    features = np.array([l5_coordinates(p, c['l5']) for p in pairs])
    return dict(pairs=np.asarray(pairs), heat=np.asarray(heat_scores), prior=prior_log_score(features, prior), candidates=[a, b], nms_radius=ra)

def choose_pair(bank, strength):
    index = 0 if strength == 0 else int(np.argmax(bank['heat'] + strength * bank['prior']))
    return (bank['pairs'][index].copy(), index)

def read_gray(path):
    with Image.open(path) as im:
        if im.mode in {'RGB', 'RGBA', 'P', 'CMYK'}:
            array = np.asarray(im.convert('L'), dtype=np.float32) / 255.0
        else:
            raw = np.asarray(im)
            if raw.dtype == np.uint8:
                array = raw.astype(np.float32) / 255.0
            else:
                array = raw.astype(np.float32)
                low, high = np.percentile(array, [0.5, 99.5])
                if not np.isfinite([low, high]).all() or high <= low:
                    raise ValueError(str(path) + ': 영상 명암 범위가 유효하지 않습니다.')
                array = np.clip((array - low) / (high - low), 0, 1)
    if array.ndim != 2 or not np.isfinite(array).all():
        raise ValueError(str(path) + ': 2차원 grayscale 영상이 필요합니다.')
    return np.ascontiguousarray(array, dtype=np.float32)

