def to_jsonable(obj):
    if isinstance(obj, dict):
        return {str(k): to_jsonable(v) for k, v in obj.items()}
    if isinstance(obj, (list, tuple)):
        return [to_jsonable(v) for v in obj]
    if isinstance(obj, np.ndarray):
        return to_jsonable(obj.tolist())
    if isinstance(obj, np.generic):
        return to_jsonable(obj.item())
    if isinstance(obj, Path):
        return str(obj)
    if isinstance(obj, float) and (not math.isfinite(obj)):
        return None
    return obj

def display_base(path, max_side=2000):
    with Image.open(path) as im:
        a = np.asarray(im.convert('L') if im.mode in ('RGB', 'RGBA', 'P', 'CMYK') else im)
    if a.ndim != 2:
        raise ValueError('2차원 X-ray 영상이 필요합니다.')
    if a.dtype != np.uint8:
        lo, hi = np.percentile(a, [0.5, 99.5])
        a = np.clip((a.astype(float) - lo) / max(hi - lo, 1e-08) * 255, 0, 255).astype(np.uint8)
    im = Image.fromarray(a).convert('RGB')
    if max_side and max(im.size) > max_side:
        im.thumbnail((max_side, max_side), Image.Resampling.LANCZOS)
    return im

