def overlay_image(path, result, layers=None, method='v2', opacity=0.2, max_side=2000, base=None):
    layers = DEFAULT_LAYERS if layers is None else layers
    im = (base.copy() if base is not None else display_base(path, max_side)).convert('RGBA')
    w, h = (result['image']['width'], result['image']['height'])
    sx, sy = (im.width / w, im.height / h)

    def pts(p):
        return [(float(x) * sx, float(y) * sy) for x, y in np.asarray(p).reshape(-1, 2)]
    lw = max(1, round(im.width / 330))
    radius = max(2, round(im.width / 200))
    fs = max(11, round(im.width / 42))
    try:
        font = ImageFont.truetype('DejaVuSans.ttf', fs)
    except OSError:
        font = ImageFont.load_default()
    fill = Image.new('RGBA', im.size)
    d = ImageDraw.Draw(fill)
    if layers.get('fh_mask'):
        for c in result.get('femoral', {}).get('segmentation_contours', []):
            color = ImageColor.getrgb(COLORS['fh' + str(c['slot'])])
            d.polygon(pts(c['points']), fill=color + (round(opacity * 255),))
    im = Image.alpha_composite(im, fill)
    d = ImageDraw.Draw(im)

    def line(p, c, closed=False):
        p = pts(p)
        if len(p) >= 2:
            d.line(p + ([p[0]] if closed else []), fill=c, width=lw, joint='curve')

    def dot(p, c):
        x, y = pts([p])[0]
        d.ellipse((x - radius, y - radius, x + radius, y + radius), fill=c, outline='black', width=1)

    def tag(p, text, c):
        x, y = pts([p])[0]
        box = d.textbbox((0, 0), text, font=font)
        tw, th = (box[2], box[3] - box[1])
        x = max(0, min(x, im.width - tw - 6))
        y = max(0, min(y, im.height - th - 6))
        d.rectangle((x, y, x + tw + 6, y + th + 6), fill=(10, 15, 23, 235))
        d.text((x + 3, y + 3 - box[1]), text, font=font, fill=c)
    spine = result.get('spine', {})
    by_id = {int(r['input_index']): r for r in spine.get('numbering', [])}
    for i, p in enumerate(spine.get('polygons', [])):
        pp = np.asarray(p['points'])
        if layers.get('spine'):
            line(pp, COLORS['spine'], True)
        if layers.get('number'):
            row = by_id.get(i, {})
            label = row.get('final_level', '?')
            tag([pp[:, 0].max() + 5, pp[:, 1].mean()], f'{i + 1}: {label}', COLORS['spine'])
    if layers.get('corners'):
        for r in spine.get('corners', []):
            c = r.get(method, {})
            for a, b in [('SA', 'SP'), ('IA', 'IP')]:
                if c.get(a) is not None and c.get(b) is not None:
                    line([c[a], c[b]], COLORS[method])
            for key in ('SA', 'SP', 'IA', 'IP'):
                if c.get(key) is not None:
                    dot(c[key], COLORS[method])
    s1 = result.get('s1', {})
    if layers.get('s1') and s1.get('points') is not None:
        line(s1['points'], COLORS['s1'])
        for p in s1['points']:
            dot(p, COLORS['s1'])
        tag(np.asarray(s1['points']).mean(0) + [10, 10], 'S1', COLORS['s1'])
    fh = result.get('femoral', {})
    if layers.get('fh_mask'):
        for c in fh.get('segmentation_contours', []):
            line(c['points'], COLORS['fh' + str(c['slot'])], True)
    if layers.get('fh_circle'):
        for c in fh.get('instances', []):
            x, y, r = (c['cx'], c['cy'], c['radius'])
            color = COLORS['fh' + str(c['slot'])]
            d.ellipse(((x - r) * sx, (y - r) * sy, (x + r) * sx, (y + r) * sy), outline=color, width=lw)
            dot([x, y], color)
            tag([x + r, y], f"FH{c['slot'] + 1}", color)
    if layers.get('hc') and fh.get('HC_LAT') is not None:
        p = fh['HC_LAT']
        x, y = (p['x'], p['y'])
        line([[x - 10, y], [x + 10, y]], 'white')
        line([[x, y - 10], [x, y + 10]], 'white')
        tag([x + 10, y + 10], 'HC', 'white')
    return im.convert('RGB')

def result_tables(result):
    number = []
    corner = []
    for row in result['spine']['numbering']:
        number.append({'후보': int(row['input_index']) + 1, '번호': row['final_level'], 'decoder': row['final_decoder'], '모델 점수': row.get('final_confidence'), 'raw 번호': row.get('raw_level'), 'raw 점수': row.get('raw_confidence')})
    for r in result['spine'].get('corners', []):
        for method in ('v1', 'v2'):
            fit = r.get(method, {})
            for key in ('SA', 'SP', 'IA', 'IP'):
                p = fit.get(key)
                if p is not None:
                    corner.append({'후보': r['candidate_index'] + 1, '번호': r['label'], '방법': method, '점': key, 'x': p[0], 'y': p[1], 'quality': fit.get('quality', ''), 'validation': r.get('validation', '')})
    s1 = []
    if result.get('s1', {}).get('points') is not None:
        s1 = [dict(point='S1_' + str(i + 1), x=p[0], y=p[1]) for i, p in enumerate(result['s1']['points'])]
    fh = [dict(head='FH' + str(c['slot'] + 1), **c) for c in result.get('femoral', {}).get('instances', [])]
    return dict(numbering=pd.DataFrame(number), corners=pd.DataFrame(corner), s1=pd.DataFrame(s1), femoral=pd.DataFrame(fh))

def export_result(path, result, spine_mask, fh_masks, output_root, models, layers=None, method='v2', opacity=0.2):
    root = Path(output_root)
    root.mkdir(parents=True, exist_ok=True)
    stem = re.sub('[^\\w.-]+', '_', Path(path).stem)[:80] or 'xray'
    folder = root / (datetime.now().strftime('%Y%m%d_%H%M%S') + '_' + stem + '_' + uuid.uuid4().hex[:8])
    folder.mkdir(exist_ok=False)
    payload = to_jsonable(copy.deepcopy(result))
    payload['models'] = to_jsonable(models)
    payload['display'] = dict(layers=layers or DEFAULT_LAYERS, corner_method=method, mask_opacity=opacity)
    payload['coordinate_system'] = 'original image pixels; origin top-left; x right; y down'
    (folder / 'results.json').write_text(json.dumps(payload, ensure_ascii=False, indent=2, allow_nan=False), encoding='utf-8')
    overlay_image(path, result, layers, method, opacity, max_side=None).save(folder / 'overlay.png')
    Image.fromarray((np.asarray(spine_mask) > 0).astype(np.uint8) * 255).save(folder / 'spine_A_binary.png')
    h, w = spine_mask.shape
    instances = np.zeros((h, w), np.uint16)
    for i, p in enumerate(result['spine']['polygons']):
        cv2.fillPoly(instances, [np.rint(p['points']).astype(np.int32)], i + 1)
    Image.fromarray(instances).save(folder / 'spine_watershed_instances.png')
    if fh_masks is not None:
        x0, y0, x1, y1 = result['femoral']['roi']
        for slot in range(2):
            full = np.zeros((h, w), np.uint8)
            full[y0:y1, x0:x1] = fh_masks[slot] * 255
            Image.fromarray(full).save(folder / f'femoral_head_{slot + 1}_mask.png')
    tables = result_tables(result)
    with pd.ExcelWriter(folder / 'coordinates.xlsx', engine='openpyxl') as writer:
        for name, table in tables.items():
            table.to_excel(writer, sheet_name=name, index=False)
    for name, table in tables.items():
        table.to_csv(folder / (name + '.csv'), index=False, encoding='utf-8-sig')
    (folder / 'README.txt').write_text('원본 영상 좌표: 좌상단 (0,0), x 오른쪽, y 아래쪽.\nspine_A_binary.png: A 모델 이진 마스크. spine_watershed_instances.png: 파편 제거/watershed 후보, 픽셀값=후보번호(1부터).\nFH1/FH2는 독립 출력 슬롯이며 좌/우 해부학적 구분이 아닙니다. 마스크와 피팅 원을 별도로 저장합니다.\nresults.json에 raw/최종 번호, v1/v2 꼭지점, S1 끝점, 골두 원/HC, 검토 사유와 모델 식별정보가 있습니다.\n번호 모델 점수는 보정된 정답 확률이 아닙니다. 정답 라벨 없는 추론이므로 정확도/Dice는 계산하지 않습니다.\nS1 입력은 예측 L5이며, 원래 S1 노트북의 GT L5 평가와 조건이 다릅니다.\n', encoding='utf-8')
    archive = Path(str(folder) + '.zip')
    with zipfile.ZipFile(archive, 'w', zipfile.ZIP_DEFLATED) as z:
        for f in sorted(folder.iterdir()):
            z.write(f, f.name)
    return (folder, archive)
